import hashlib
import json
import shutil
import subprocess
import time
from tools import p4_full_preflight as p

root = p.ROOT
head = "ccc80fd8d2d700654a9003cc70e3785628275f99"
main = "269e34eeeac920c29f2d684cfe37c93a95c73057"
relative = (
    "reports/P4/fixed-ccc80fd8d2d700654a9003cc70e3785628275f99/"
    "inventory-formal6.json"
)
report = {
    "schema": "p4-readonly-prerequisite-inventory-v2",
    "status": "FAIL",
    "fixed_code_sha": head,
    "attempts": 0,
    "SQL_executed": False,
    "count_executed": False,
    "GPU_executed": False,
    "inventory_complete": False,
    "local_finalization_attempts": [],
}
failure = None
source_before = None
snapshot_started = False
config_path_before = None
config_bytes_before = None
config_binding_before = None

def config_binding(path, data):
    return {
        "path": path.as_posix(),
        "size": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }

def observation(path, label):
    observed = {}
    report[label] = observed
    operations = (
        ("identity", lambda: path.stat()),
        ("sidecars", lambda: p.corpus.sidecars(path)),
        ("sha256", lambda: p.exact.sha(path)),
    )
    for name, operation in operations:
        started = time.monotonic()
        try:
            value = operation()
            if name == "identity":
                observed["identity"] = {
                    "size": value.st_size,
                    "mtime_ns": value.st_mtime_ns,
                    "dev": value.st_dev,
                    "ino": value.st_ino,
                }
                observed["atime_ns"] = value.st_atime_ns
            else:
                observed[name] = value
        except Exception as error:
            observed[name + "_error"] = repr(error)
        finally:
            observed[name + "_duration_s"] = time.monotonic() - started
    return observed

def observation_ok(observed):
    return (
        all(key in observed for key in ("identity", "sidecars", "sha256"))
        and not any(key.endswith("_error") for key in observed)
    )

def local_source():
    records = {}
    for name in source_before["source_inventory"]:
        data = p.contained(name).read_bytes()
        records[name] = {
            "checkout_size": len(data),
            "checkout_sha256": hashlib.sha256(data).hexdigest(),
        }
    return records

def local_finalize():
    record = {
        "attempt": len(report["local_finalization_attempts"]) + 1,
        "errors": {},
    }
    report["local_finalization_attempts"].append(record)
    errors = record["errors"]

    if source_before is not None:
        try:
            actual = local_source()
            record["source_after"] = actual
            expected = {
                name: {
                    "checkout_size": ref["checkout_size"],
                    "checkout_sha256": ref["checkout_sha256"],
                }
                for name, ref in source_before["source_inventory"].items()
            }
            p.require(actual == expected, "local source changed")
        except Exception as error:
            errors["source"] = repr(error)
    else:
        record["source_check"] = "NOT_RUN_INITIAL_BINDING_UNAVAILABLE"

    try:
        p.require(
            config_binding_before is not None
            and config_bytes_before is not None,
            "initial canonical byte binding unavailable",
        )
        current_path = p.controlled_path(p.CONFIG, root, strict=True)
        current_bytes = current_path.read_bytes()
        current_binding = config_binding(current_path, current_bytes)
        record["canonical_binding_after"] = current_binding
        p.require(
            current_path == config_path_before
            and current_binding == config_binding_before
            and current_bytes == config_bytes_before,
            "canonical path or original bytes changed",
        )
    except Exception as error:
        errors["canonical_original_bytes"] = repr(error)

    try:
        with p.config_guard(p.exact.load(p.CONFIG), root):
            pass
    except Exception as error:
        errors["canonical_current_contract"] = repr(error)

    try:
        p.assert_no_product(root)
    except Exception as error:
        errors["product"] = repr(error)

    record["status"] = "PASS" if not errors else "FAIL"
    return not errors

try:
    config_path_before = p.controlled_path(p.CONFIG, root, strict=True)
    config_bytes_before = config_path_before.read_bytes()
    config_binding_before = config_binding(
        config_path_before, config_bytes_before
    )
    report["canonical_binding_before"] = config_binding_before
    report["canonical_raw_hex_before"] = config_bytes_before.hex()

    config = p.exact.load(config_path_before)
    p.require(
        config_path_before.read_bytes() == config_bytes_before,
        "canonical changed during initial load",
    )
    path = p.contained(config["snapshot"]["path"])
    p.assert_no_product(root)
    with p.config_guard(config, root) as canonical:
        report["canonical"] = canonical
    p.require(
        config_path_before.read_bytes() == config_bytes_before,
        "canonical changed during initial validation",
    )

    source_before = p.source_inventory(head, root)
    report.update(source_before)
    local_main = subprocess.check_output(
        ["git", "rev-parse", "main"], cwd=root, text=True
    ).strip()
    p.require(local_main == main, "local main changed")
    remote_main = subprocess.check_output(
        ["git", "ls-remote", "origin", "refs/heads/main"],
        cwd=root, text=True,
    ).split()
    p.require(remote_main == [main, "refs/heads/main"], "remote main changed")
    report["main_local"] = local_main
    report["main_remote"] = remote_main

    snapshot_started = True
    try:
        before = observation(path, "snapshot_before")
        p.require(
            observation_ok(before)
            and before["identity"]["size"] == config["snapshot"]["size"]
            and before["sha256"] == config["snapshot"]["sha256"],
            "snapshot before verification failed",
        )
        verified = p.inventory()
        report.update(
            inventory_complete=True,
            inventory_sha256=verified["inventory_sha256"],
            bindings=verified["bindings"],
            historical_job_bindings=verified["historical_job_bindings"],
            pack=verified["pack"],
            encoder_contract=verified["contract"],
        )
        report["free_bytes"] = shutil.disk_usage(root).free
        report["resource_caps"] = {
            "max_audit_bytes": 1073741824,
            "audit_batch_size": 1024,
            "max_document_text_bytes": 16777216,
            "limitation": "Caps may BLOCKED; exact FULL count unknown",
        }
        report["initial_reservation"] = p.initial_stage_gate(
            None, root, 1073741824
        )
    except Exception as error:
        report["inventory_error"] = repr(error)
        failure = error
    finally:
        after = observation(path, "snapshot_after")
        before = report["snapshot_before"]
        report["after_errors"] = {
            key: value
            for key, value in after.items()
            if key.endswith("_error")
        }
        checks = {
            "observations_complete": (
                observation_ok(before) and observation_ok(after)
            ),
            "identity": (
                "identity" in before
                and "identity" in after
                and before["identity"] == after["identity"]
            ),
            "sidecars": (
                "sidecars" in before
                and "sidecars" in after
                and before["sidecars"] == after["sidecars"]
            ),
            "whole_hash": (
                before.get("sha256")
                == after.get("sha256")
                == config["snapshot"]["sha256"]
            ),
        }
        report["snapshot_checks"] = checks
        if not all(checks.values()) and failure is None:
            failure = ValueError("snapshot observations failed")

    local_ok = local_finalize()
    if failure is None and local_ok:
        try:
            source_after = p.source_inventory(head, root)
            report["source_after"] = source_after
            p.require(source_after == source_before, "source changed")
            post_main = subprocess.check_output(
                ["git", "ls-remote", "origin", "refs/heads/main"],
                cwd=root, text=True,
            ).split()
            p.require(post_main == [main, "refs/heads/main"], "remote main changed")
            report["remote_postguards"] = "PASS"
        except Exception as error:
            report["remote_postguard_error"] = repr(error)
            failure = error
    else:
        report["remote_postguards"] = "NOT_RUN_STOP"

    final_local_ok = local_finalize()
    if (
        failure is None
        and local_ok
        and final_local_ok
        and report["inventory_complete"]
    ):
        report["status"] = "PASS"
except Exception as error:
    report["preflight_error"] = repr(error)
    if failure is None:
        failure = error
    local_finalize()
    report["remote_postguards"] = "NOT_RUN_STOP"

report["snapshot_started"] = snapshot_started
if report["status"] != "PASS" and failure is None:
    failure = ValueError("inventory or local finalization failed")
if failure is not None:
    report["error"] = repr(failure)

output = p.controlled_path(relative, root, strict=False)
p.require(not output.exists(), "inventory receipt already exists")
with output.open("xb") as stream:
    stream.write(p.chunks.canonical(report))
print(json.dumps({
    "status": report["status"],
    "error": report.get("error"),
}, ensure_ascii=False))
if failure is not None:
    raise failure
